"use client";

import { useCallback, useEffect, useId, useLayoutEffect, useMemo, useRef, useState, type KeyboardEvent } from "react";
import { AnimatePresence, LayoutGroup, motion, type Variants } from "motion/react";

import { cn } from "../lib/cn";
import { groupBlur, joinIds, useFocusProxyRef, useMergedRef } from "../lib/form";
import { duration, ease, spring } from "../motion/tokens";
import { useSheenReducedMotion } from "../hooks/use-preferences";
import {
  addDays,
  addMonths,
  addYears,
  clampDate,
  compareDays,
  dayKey,
  fromDayKey,
  endOfMonth,
  endOfWeek,
  formatDate,
  getMonthGrid,
  getWeekStart,
  getWeekdayNames,
  isSameDay,
  isWithinRange,
  monthKey,
  startOfDay,
  startOfMonth,
  startOfWeek,
  toISODate,
  type DateRange,
  type Weekday,
} from "./date-utils";
import { useControllable } from "../hooks/use-controllable";
import { isRtlAt, useResolvedDirection } from "../hooks/use-direction";

import { defaultCalendarLabels, type CalendarProps, type View, EMPTY_RANGE, RANGE_SCAN_DAYS } from "./parts/model";
import { type DayState, MonthGrid, MonthYearPicker, NavButton, CaptionButton } from "./parts/grid";

export {
  type CalendarLabels,
  defaultCalendarLabels,
  type CalendarSingleProps,
  type CalendarRangeProps,
  type CalendarProps,
} from "./parts/model";
/**
 * A locale-aware month grid for picking one date or a date range. Week start, month and weekday
 * names and even the digits come from Intl (`locale="ar-EG"` starts on Saturday in Arabic
 * numerals). The caption opens a month grid and then a year grid for long jumps.
 *
 * Props: see {@link CalendarProps}. Common: `locale`, `today` (pass a fixed date for prerender
 * and tests), `weekStartsOn`, `min`, `max`, `isDateDisabled`, `month` / `defaultMonth` /
 * `onMonthChange`, `numberOfMonths` (1), `showOutsideDays`, `fixedWeeks` (true), `fluid`
 * (false), `autoFocus` (false), `labels`, `className`. Single mode: `value`, `defaultValue`,
 * `onValueChange`. Range mode (`mode="range"`): the same with `{ start, end }`, plus
 * `allowUnavailableInRange`.
 *
 * Keyboard: WAI-ARIA date grid: arrows move by day or week, Home / End go to the week's edges, Page Up / Down change month, Shift + Page Up / Down change year. One day is in the tab order (roving tabindex); right-to-left flips Left and Right. Enter or Space selects.
 * Accessibility: A `role="grid"` per month with named days (date, today, selected, range start and end, unavailable); unavailable days stay focusable but cannot be selected. A polite live region announces month changes. Selection never relies on colour alone.
 * Glass: Flat cells on the parent surface; the selected-day pill is a gradient with no blur.
 * Motion: Months slide in the direction of travel, the selected pill glides between days and the month and year grids zoom in. Reduced motion cross-fades or jumps instead.
 *
 * @example
 * ```tsx
 * import { useState } from "react";
 * import { Calendar } from "@sheenui/theme";
 *
 * export function Picker() {
 *   const [date, setDate] = useState<Date | null>(null);
 *   return <Calendar value={date} onValueChange={setDate} min={new Date()} aria-label="Pick a date" />;
 * }
 * ```
 *
 * @see /forms/calendar
 */
export function Calendar(props: CalendarProps) {
  const {
    locale,
    today: todayProp,
    weekStartsOn,
    min: minProp,
    max: maxProp,
    isDateDisabled,
    month: monthProp,
    defaultMonth,
    onMonthChange,
    numberOfMonths = 1,
    showOutsideDays,
    fixedWeeks = true,
    fluid = false,
    autoFocus = false,
    "aria-label": ariaLabel,
    labels: labelsProp,
    className,
    name,
    ref,
    onBlur,
    "aria-invalid": ariaInvalid,
    "aria-describedby": ariaDescribedBy,
  } = props;
  const labels = { ...defaultCalendarLabels, ...labelsProp };
  const range = props.mode === "range";
  const monthCount = Math.max(1, Math.floor(numberOfMonths));
  const outsideDays = showOutsideDays ?? monthCount === 1;
  const reduced = useSheenReducedMotion();
  const id = useId();

  const min = minProp ? startOfDay(minProp) : null;
  const max = maxProp ? startOfDay(maxProp) : null;
  const localeWeekStart = useMemo(() => getWeekStart(locale), [locale]);
  const weekStart: Weekday = weekStartsOn ?? localeWeekStart;
  const today = startOfDay(todayProp ?? new Date());

  // ---- value ----
  const [single, setSingle] = useControllable<Date | null>(
    range ? undefined : props.value,
    () => (range ? null : (props.defaultValue ?? null)),
    range ? undefined : props.onValueChange,
  );
  const [rangeValue, setRange] = useControllable<DateRange>(
    range ? props.value : undefined,
    () => (range ? (props.defaultValue ?? EMPTY_RANGE) : EMPTY_RANGE),
    range ? props.onValueChange : undefined,
  );
  const selectedAnchor = range ? (rangeValue.start ?? null) : single;

  // ---- visible month ----
  const [month, setMonthState] = useControllable<Date>(
    monthProp ? startOfMonth(monthProp) : undefined,
    () => startOfMonth(clampDate(defaultMonth ?? selectedAnchor ?? today, min, max)),
    onMonthChange,
  );
  const [direction, setDirection] = useState(1);
  const firstVisible = startOfMonth(month);
  const lastVisible = endOfMonth(addMonths(firstVisible, monthCount - 1));
  const isVisible = (date: Date) => isWithinRange(date, firstVisible, lastVisible);

  // min / max are compared by day, so their keys are all the callbacks below depend on.
  const minKey = min ? dayKey(min) : null;
  const maxKey = max ? dayKey(max) : null;
  const isUnavailable = useCallback(
    (date: Date) =>
      (minKey !== null && dayKey(date) < minKey) ||
      (maxKey !== null && dayKey(date) > maxKey) ||
      (isDateDisabled?.(date) ?? false),
    [minKey, maxKey, isDateDisabled],
  );

  // ---- focus (roving tabindex) ----
  const [focusedDate, setFocusedDate] = useState<Date>(() => clampDate(selectedAnchor ?? today, min, max));
  const focusTarget = isVisible(focusedDate)
    ? focusedDate
    : selectedAnchor && isVisible(selectedAnchor)
      ? selectedAnchor
      : isVisible(today)
        ? today
        : firstVisible;
  const pendingFocus = useRef(autoFocus);
  const rootRef = useRef<HTMLDivElement>(null);
  const focusRef = useFocusProxyRef(ref, "[data-day][tabindex='0']:not(:disabled)", "[data-day]:not(:disabled)");
  const mergedRootRef = useMergedRef(rootRef, focusRef);
  // Right-to-left layouts slide months the other way (the nearest `dir` ancestor counts).
  const rtl = useResolvedDirection(undefined, rootRef) === "rtl";
  const slideDir = rtl ? -direction : direction;

  useLayoutEffect(() => {
    if (!pendingFocus.current) return;
    pendingFocus.current = false;
    rootRef.current?.querySelector<HTMLElement>(`[data-present] [data-day="${toISODate(focusTarget)}"]`)?.focus();
  });

  // ---- view: days / months / years ----
  const [view, setView] = useState<View>("days");
  /** Which month panel the month / year picker covers (the one whose caption was clicked). */
  const [pickerPanel, setPickerPanel] = useState(0);
  const [pickerYear, setPickerYear] = useState(() => firstVisible.getFullYear());
  // If the panel count shrinks while the picker is open (a resize), keep it on a panel that exists.
  const activePanel = Math.min(pickerPanel, monthCount - 1);

  // ---- range preview ----
  const [preview, setPreview] = useState<Date | null>(null);
  const picking = range && rangeValue.start !== null && rangeValue.end === null;
  const anchor = picking ? rangeValue.start : null;

  const anchorKey = anchor ? dayKey(anchor) : null;
  const crossesUnavailable = range && props.allowUnavailableInRange;
  /** Nearest unavailable days around the anchor: a range can't cross them. */
  const limits = useMemo(() => {
    if (anchorKey === null || crossesUnavailable) return null;
    // Rebuilt from the day keys: a new Date for the same day must not rescan up to RANGE_SCAN_DAYS days.
    const anchor = fromDayKey(anchorKey);
    const min = minKey === null ? null : fromDayKey(minKey);
    const max = maxKey === null ? null : fromDayKey(maxKey);
    let before: Date | null = null;
    let after: Date | null = null;
    for (let i = 1; i <= RANGE_SCAN_DAYS && !before; i++) {
      const d = addDays(anchor, -i);
      if (min && compareDays(d, min) < 0) break;
      if (isUnavailable(d)) before = d;
    }
    for (let i = 1; i <= RANGE_SCAN_DAYS && !after; i++) {
      const d = addDays(anchor, i);
      if (max && compareDays(d, max) > 0) break;
      if (isUnavailable(d)) after = d;
    }
    return { before, after };
  }, [anchorKey, minKey, maxKey, isUnavailable, crossesUnavailable]);

  const isBlocked = (date: Date) => {
    if (isUnavailable(date)) return true;
    if (!limits) return false;
    return (
      (limits.before !== null && compareDays(date, limits.before) <= 0) ||
      (limits.after !== null && compareDays(date, limits.after) >= 0)
    );
  };

  // ---- announcements ----
  const [announcement, setAnnouncement] = useState("");
  const captionFormat = { month: "long", year: "numeric" } as const;
  const visibleCaption = Array.from({ length: monthCount }, (_, i) =>
    formatDate(addMonths(firstVisible, i), locale, captionFormat),
  ).join(" – ");
  const lastCaption = useRef(visibleCaption);
  const monthChanged = labels.monthChanged;
  useEffect(() => {
    if (lastCaption.current === visibleCaption) return;
    lastCaption.current = visibleCaption;
    setAnnouncement(monthChanged(visibleCaption));
  }, [visibleCaption, monthChanged]);

  // ---- navigation ----
  const prevDisabled = min !== null && monthKey(addMonths(firstVisible, -1)) < monthKey(min);
  const nextDisabled = max !== null && monthKey(addMonths(firstVisible, monthCount)) > monthKey(max);

  function goToMonth(next: Date, dir: number) {
    const target = startOfMonth(next);
    if (monthKey(target) === monthKey(firstVisible)) return;
    setDirection(dir);
    setMonthState(target);
  }

  function step(delta: number) {
    if ((delta < 0 && prevDisabled) || (delta > 0 && nextDisabled)) return;
    goToMonth(addMonths(firstVisible, delta), delta);
    // The roving day follows, so Tab back into the grid lands on the same day of the new month.
    setFocusedDate((d) => clampDate(addMonths(isVisible(d) ? d : focusTarget, delta), min, max));
  }

  function moveFocus(date: Date) {
    const next = clampDate(date, min, max);
    if (compareDays(next, firstVisible) < 0) goToMonth(next, -1);
    else if (compareDays(next, lastVisible) > 0) goToMonth(addMonths(startOfMonth(next), -(monthCount - 1)), 1);
    setFocusedDate(next);
    if (picking) setPreview(next);
    pendingFocus.current = true;
  }

  function onGridKeyDown(event: KeyboardEvent<HTMLTableElement>) {
    const rtl = isRtlAt(event.currentTarget);
    const d = focusTarget;
    let next: Date;
    switch (event.key) {
      case "ArrowLeft":
        next = addDays(d, rtl ? 1 : -1);
        break;
      case "ArrowRight":
        next = addDays(d, rtl ? -1 : 1);
        break;
      case "ArrowUp":
        next = addDays(d, -7);
        break;
      case "ArrowDown":
        next = addDays(d, 7);
        break;
      case "Home":
        next = startOfWeek(d, weekStart);
        break;
      case "End":
        next = endOfWeek(d, weekStart);
        break;
      case "PageUp":
        next = event.shiftKey ? addYears(d, -1) : addMonths(d, -1);
        break;
      case "PageDown":
        next = event.shiftKey ? addYears(d, 1) : addMonths(d, 1);
        break;
      default:
        return;
    }
    event.preventDefault();
    moveFocus(next);
  }

  function select(date: Date) {
    setFocusedDate(date);
    if (!range) {
      if (isUnavailable(date)) return;
      setSingle(date);
      return;
    }
    if (isBlocked(date)) return;
    if (!picking || !rangeValue.start) {
      setRange({ start: date, end: null });
      setPreview(date);
      return;
    }
    const start = rangeValue.start;
    setRange(compareDays(date, start) < 0 ? { start: date, end: start } : { start, end: date });
    setPreview(null);
  }

  // ---- per-day state ----
  const rangeStart = range ? rangeValue.start : null;
  const rangeEnd = range ? rangeValue.end : null;
  const previewEnd = picking && preview && !isBlocked(preview) ? preview : null;
  const [previewFrom, previewTo] =
    anchor && previewEnd
      ? compareDays(previewEnd, anchor) < 0
        ? [previewEnd, anchor]
        : [anchor, previewEnd]
      : [null, null];

  const dayState = (date: Date, inMonth: boolean): DayState => {
    const selectedSingle = !range && isSameDay(date, single);
    const isStart = isSameDay(date, rangeStart);
    const isEnd = isSameDay(date, rangeEnd);
    const inRange = !!rangeStart && !!rangeEnd && isWithinRange(date, rangeStart, rangeEnd);
    const inPreview = !!previewFrom && isWithinRange(date, previewFrom, previewTo);
    return {
      inMonth,
      today: isSameDay(date, today),
      unavailable: range ? isBlocked(date) : isUnavailable(date),
      selected: selectedSingle || isStart || isEnd,
      rangeStart: isStart && !!rangeEnd ? !isSameDay(rangeStart, rangeEnd) : false,
      rangeEnd: isEnd && !!rangeStart ? !isSameDay(rangeStart, rangeEnd) : false,
      inRange: inRange && !isStart && !isEnd,
      previewStart: inPreview && isSameDay(date, previewFrom),
      previewEnd: inPreview && isSameDay(date, previewTo),
      inPreview,
      previewCap: !!previewEnd && isSameDay(date, previewEnd) && !isSameDay(date, anchor),
      focusTarget: isSameDay(date, focusTarget),
    };
  };

  // Some locales' "short" weekdays are whole words (Arabic): use the narrow form there.
  const shortNames = getWeekdayNames(locale, weekStart, "short");
  const weekdaysShort = shortNames.some((n) => n.length > 5)
    ? getWeekdayNames(locale, weekStart, "narrow")
    : shortNames;
  const weekdaysLong = getWeekdayNames(locale, weekStart, "long");
  const dayNumber = { day: "numeric" } as const;
  const dayName = { weekday: "long", year: "numeric", month: "long", day: "numeric" } as const;

  function openMonths(panel: number) {
    setPickerPanel(panel);
    setPickerYear(addMonths(firstVisible, panel).getFullYear());
    setView("months");
  }

  function closePicker(focusDays: boolean) {
    setView("days");
    if (focusDays) pendingFocus.current = true;
  }

  const slide: Variants = reduced
    ? {
        enter: { opacity: 0 },
        center: { opacity: 1, transition: { duration: duration.fast } },
        exit: { opacity: 0, transition: { duration: duration.exit, ease: ease.exit } },
      }
    : {
        enter: (dir: number) => ({ x: dir * 32, opacity: 0 }),
        center: { x: 0, opacity: 1, transition: { x: spring.snappy, opacity: { duration: duration.fast } } },
        exit: (dir: number) => ({ x: dir * -32, opacity: 0, transition: { duration: duration.exit, ease: ease.exit } }),
      };

  return (
    // eslint-disable-next-line jsx-a11y/no-static-element-interactions -- onBlur only reports focus leaving the calendar to a form library
    <div
      ref={mergedRootRef}
      onBlur={groupBlur(onBlur)}
      role={ariaLabel ? "group" : undefined}
      aria-label={ariaLabel}
      aria-describedby={joinIds(ariaDescribedBy)}
      data-invalid={ariaInvalid === true || ariaInvalid === "true" ? "" : undefined}
      data-slot="calendar"
      className={cn("relative flex max-w-full flex-col", fluid ? "w-full" : "w-fit", className)}
    >
      <div className="sr-only" aria-live="polite" aria-atomic="true">
        {announcement}
      </div>

      {/* Month panels. The month / year picker opens over the panel whose caption was clicked;
          the days stay mounted under it (inert), so the size never jumps, and other panels dim. */}
      <div className={cn("flex flex-wrap gap-x-6 gap-y-5", fluid && "w-full")}>
        <LayoutGroup id={id}>
          {Array.from({ length: monthCount }, (_, index) => {
            const m = addMonths(firstVisible, index);
            const caption = formatDate(m, locale, captionFormat);
            const covered = view !== "days" && activePanel === index;
            const dimmed = view !== "days" && activePanel !== index;
            return (
              <div key={index} className={cn("relative flex min-w-0 flex-col", fluid ? "w-full flex-1" : "")}>
                <motion.div
                  inert={view !== "days"}
                  initial={false}
                  animate={
                    covered ? { opacity: 0, scale: reduced ? 1 : 0.96 } : { opacity: dimmed ? 0.35 : 1, scale: 1 }
                  }
                  transition={
                    view === "days"
                      ? { opacity: { duration: duration.base }, scale: spring.snappy }
                      : { duration: duration.exit, ease: ease.exit }
                  }
                  className="flex min-w-0 flex-col gap-2"
                >
                  <div className="flex h-10 items-center gap-1 any-pointer-coarse:h-11">
                    {index === 0 ? (
                      <NavButton
                        label={labels.previousMonth}
                        disabled={prevDisabled}
                        onClick={() => step(-1)}
                        dir="prev"
                      />
                    ) : (
                      <span aria-hidden className="size-8 shrink-0 any-pointer-coarse:size-11" />
                    )}
                    <CaptionButton
                      label={labels.chooseMonth(caption)}
                      expanded={false}
                      onClick={() => openMonths(index)}
                      motionKey={monthKey(m)}
                      direction={direction}
                      reduced={reduced}
                    >
                      {caption}
                    </CaptionButton>
                    {index === monthCount - 1 ? (
                      <NavButton label={labels.nextMonth} disabled={nextDisabled} onClick={() => step(1)} dir="next" />
                    ) : (
                      <span aria-hidden className="size-8 shrink-0 any-pointer-coarse:size-11" />
                    )}
                  </div>

                  {/* popLayout: the leaving month is lifted out of the flow, so both slide at once. */}
                  <div className="relative">
                    <AnimatePresence initial={false} mode="popLayout" custom={slideDir}>
                      <motion.div
                        key={monthKey(m)}
                        custom={slideDir}
                        variants={slide}
                        initial="enter"
                        animate="center"
                        exit="exit"
                      >
                        <MonthGrid
                          caption={caption}
                          weeks={getMonthGrid(m, weekStart, fixedWeeks)}
                          month={m}
                          range={range}
                          fluid={fluid}
                          outsideDays={outsideDays}
                          weekdaysShort={weekdaysShort}
                          weekdaysLong={weekdaysLong}
                          dayState={dayState}
                          formatNumber={(d) => formatDate(d, locale, dayNumber)}
                          formatName={(d, s) =>
                            [
                              formatDate(d, locale, dayName),
                              s.rangeStart && labels.rangeStart,
                              s.rangeEnd && labels.rangeEnd,
                            ]
                              .filter(Boolean)
                              .join(", ")
                          }
                          pillId={reduced || range ? undefined : `${id}-pill`}
                          onSelect={select}
                          onFocusDay={(d) => {
                            setFocusedDate(d);
                            if (picking) setPreview(d);
                          }}
                          onHoverDay={(d) => picking && setPreview(d)}
                          onLeave={() => setPreview(null)}
                          onKeyDown={onGridKeyDown}
                        />
                      </motion.div>
                    </AnimatePresence>
                  </div>
                </motion.div>

                <AnimatePresence>
                  {covered && (
                    <MonthYearPicker
                      key="picker"
                      view={view}
                      year={pickerYear}
                      visibleMonth={m}
                      today={today}
                      min={min}
                      max={max}
                      locale={locale}
                      labels={labels}
                      reduced={reduced}
                      onYearChange={setPickerYear}
                      onShowYears={() => setView("years")}
                      onPickYear={(y) => {
                        setPickerYear(y);
                        setView("months");
                      }}
                      onPickMonth={(monthIndex) => {
                        // The picked month lands in the panel it was picked from.
                        const target = new Date(pickerYear, monthIndex, 1);
                        const first = addMonths(target, -index);
                        goToMonth(first, monthKey(first) < monthKey(firstVisible) ? -1 : 1);
                        setFocusedDate(
                          clampDate(
                            new Date(
                              pickerYear,
                              monthIndex,
                              Math.min(focusTarget.getDate(), endOfMonth(target).getDate()),
                            ),
                            min,
                            max,
                          ),
                        );
                        closePicker(true);
                      }}
                      onClose={() => closePicker(true)}
                    />
                  )}
                </AnimatePresence>
              </div>
            );
          })}
        </LayoutGroup>
      </div>
      {name && !range && <input type="hidden" name={name} value={single ? toISODate(single) : ""} />}
      {name && range && (
        <input type="hidden" name={`${name}-start`} value={rangeValue.start ? toISODate(rangeValue.start) : ""} />
      )}
      {name && range && (
        <input type="hidden" name={`${name}-end`} value={rangeValue.end ? toISODate(rangeValue.end) : ""} />
      )}
    </div>
  );
}

/**
 * Date helpers for Calendar and DatePicker: plain `Date` objects at local midnight, and
 * `Intl` for every locale-dependent bit (week start, month and weekday names, digits).
 * No dependencies.
 *
 * All arithmetic goes through `new Date(year, month, day)`, which normalises overflow
 * (day 32 → next month) and never lands on the wrong day around daylight-saving changes.
 */

export type DateRange = { start: Date | null; end: Date | null };

/** 0 = Sunday … 6 = Saturday, like Date.getDay(). */
export type Weekday = 0 | 1 | 2 | 3 | 4 | 5 | 6;

/**
 * A new Date at local midnight of the same calendar day. Pure; uses the runtime's local time zone, no
 * DOM, so it is safe to call on the server.
 */
export function startOfDay(date: Date): Date {
  return new Date(date.getFullYear(), date.getMonth(), date.getDate());
}

/**
 * A new Date moved by `days` calendar days (negative goes back), at local midnight; DST-safe. Pure, no
 * DOM: safe on the server (local time zone of the runtime).
 */
export function addDays(date: Date, days: number): Date {
  return new Date(date.getFullYear(), date.getMonth(), date.getDate() + days);
}

/**
 * Number of days in a month; `month` is 0-based like `Date#getMonth`. Pure, no DOM: safe on the
 * server.
 */
export function daysInMonth(year: number, month: number): number {
  return new Date(year, month + 1, 0).getDate();
}

/** Adds months and clamps the day: Jan 31 + 1 month → Feb 28 (or 29). */
export function addMonths(date: Date, months: number): Date {
  const first = new Date(date.getFullYear(), date.getMonth() + months, 1);
  const day = Math.min(date.getDate(), daysInMonth(first.getFullYear(), first.getMonth()));
  return new Date(first.getFullYear(), first.getMonth(), day);
}

/**
 * A new Date `years` years later (negative goes back); Feb 29 clamps to Feb 28 in non-leap years.
 * Pure, no DOM: safe on the server.
 */
export function addYears(date: Date, years: number): Date {
  return addMonths(date, years * 12);
}

/**
 * A new Date on the first day of the month of `date`, at local midnight. Pure, no DOM: safe on the
 * server.
 */
export function startOfMonth(date: Date): Date {
  return new Date(date.getFullYear(), date.getMonth(), 1);
}

/**
 * A new Date on the last day of the month of `date`, at local midnight. Pure, no DOM: safe on the
 * server.
 */
export function endOfMonth(date: Date): Date {
  return new Date(date.getFullYear(), date.getMonth() + 1, 0);
}

/** A sortable number for a calendar day (YYYYMMDD). Time of day is ignored. */
export function dayKey(date: Date): number {
  return date.getFullYear() * 10000 + date.getMonth() * 100 + date.getDate();
}

/** The day a `dayKey` stands for, at local midnight. */
export function fromDayKey(key: number): Date {
  return new Date(Math.floor(key / 10000), Math.floor((key % 10000) / 100), key % 100);
}

/** A sortable number for a calendar month (YYYYMM). */
export function monthKey(date: Date): number {
  return date.getFullYear() * 100 + date.getMonth();
}

/**
 * True when both dates fall on the same local calendar day; false if either is null or undefined.
 * Pure, no DOM: safe on the server.
 */
export function isSameDay(a: Date | null | undefined, b: Date | null | undefined): boolean {
  return !!a && !!b && dayKey(a) === dayKey(b);
}

/** True when both dates fall in the same local year and month. Pure, no DOM: safe on the server. */
export function isSameMonth(a: Date, b: Date): boolean {
  return monthKey(a) === monthKey(b);
}

/** Negative when a is before b, 0 on the same day, positive after. */
export function compareDays(a: Date, b: Date): number {
  return dayKey(a) - dayKey(b);
}

/** Whole days from a to b (b - a), DST-safe. */
export function differenceInDays(a: Date, b: Date): number {
  const utcA = Date.UTC(a.getFullYear(), a.getMonth(), a.getDate());
  const utcB = Date.UTC(b.getFullYear(), b.getMonth(), b.getDate());
  return Math.round((utcB - utcA) / 86_400_000);
}

/**
 * True when the calendar day of `date` is between `start` and `end`, both ends included (time of day
 * ignored). Pure, no DOM: safe on the server.
 */
export function isWithinRange(date: Date, start: Date, end: Date): boolean {
  const key = dayKey(date);
  return key >= dayKey(start) && key <= dayKey(end);
}

/**
 * Pulls `date` into the optional `min` / `max` days: returns `min` or `max` (at local midnight) when
 * outside them, otherwise `date` itself. Pure, no DOM: safe on the server.
 */
export function clampDate(date: Date, min?: Date | null, max?: Date | null): Date {
  if (min && compareDays(date, min) < 0) return startOfDay(min);
  if (max && compareDays(date, max) > 0) return startOfDay(max);
  return date;
}

/** First day of the week that contains `date`. */
export function startOfWeek(date: Date, weekStart: Weekday): Date {
  const offset = (date.getDay() - weekStart + 7) % 7;
  return addDays(date, -offset);
}

/**
 * The last day of the week that contains `date`, for a week starting on `weekStart` (0 = Sunday).
 * Pure, no DOM: safe on the server.
 */
export function endOfWeek(date: Date, weekStart: Weekday): Date {
  return addDays(startOfWeek(date, weekStart), 6);
}

/** "2026-10-29" for the local calendar day (what a form submits). */
export function toISODate(date: Date): string {
  const pad = (n: number, width = 2) => String(n).padStart(width, "0");
  return `${pad(date.getFullYear(), 4)}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}`;
}

/** Parses "YYYY-MM-DD" as a local date. Returns null for anything else or an impossible day. */
export function parseISODate(value: string): Date | null {
  const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(value.trim());
  if (!match) return null;
  const [y, m, d] = [Number(match[1]), Number(match[2]) - 1, Number(match[3])];
  const date = new Date(y, m, d);
  return date.getFullYear() === y && date.getMonth() === m && date.getDate() === d ? date : null;
}

/**
 * The weeks of a month as rows of 7 days, starting on `weekStart`. Days from the
 * neighbouring months fill the first and last rows. With `fixedWeeks`, always 6 rows,
 * so the calendar never changes height between months.
 */
export function getMonthGrid(month: Date, weekStart: Weekday, fixedWeeks = true): Date[][] {
  const first = startOfMonth(month);
  const start = startOfWeek(first, weekStart);
  const lastDay = endOfMonth(month);
  const weekCount = fixedWeeks ? 6 : Math.ceil((differenceInDays(start, lastDay) + 1) / 7);
  return Array.from({ length: weekCount }, (_, week) =>
    Array.from({ length: 7 }, (_, day) => addDays(start, week * 7 + day)),
  );
}

/* ---------- Intl ---------- */

const formatterCache = new Map<string, Intl.DateTimeFormat>();

/** Cached Intl.DateTimeFormat: building one is far slower than formatting with it. */
export function getDateFormatter(locale: string | undefined, options: Intl.DateTimeFormatOptions): Intl.DateTimeFormat {
  const key = `${locale ?? ""}|${JSON.stringify(options)}`;
  let formatter = formatterCache.get(key);
  if (!formatter) {
    formatter = new Intl.DateTimeFormat(locale, options);
    formatterCache.set(key, formatter);
  }
  return formatter;
}

/**
 * Formats a date with `Intl.DateTimeFormat` for a locale and options, through the formatter cache. No
 * DOM, but the output depends on the runtime's ICU data and time zone, so pass an explicit locale when
 * server and browser must match.
 */
export function formatDate(date: Date, locale: string | undefined, options: Intl.DateTimeFormatOptions): string {
  return getDateFormatter(locale, options).format(date);
}

/**
 * "Oct 3 – 10, 2026": Intl's own range format, which drops the parts both ends share.
 * Newer ICU versions (Node 24) put thin spaces (U+2009) around the dash where browsers still use
 * plain ones, so server-rendered text would not match the browser's: they are normalised to plain spaces.
 */
export function formatDateRange(
  start: Date,
  end: Date,
  locale: string | undefined,
  options: Intl.DateTimeFormatOptions,
): string {
  const formatter = getDateFormatter(locale, options);
  if (typeof formatter.formatRange === "function") return formatter.formatRange(start, end).replace(/\u2009/g, " ");
  return `${formatter.format(start)} – ${formatter.format(end)}`;
}

/** A known Sunday, used to read weekday names in any locale. */
const SUNDAY = new Date(2024, 0, 7);

/** Weekday names in display order, starting on `weekStart`. */
export function getWeekdayNames(
  locale: string | undefined,
  weekStart: Weekday,
  style: "long" | "short" | "narrow",
): string[] {
  const formatter = getDateFormatter(locale, { weekday: style });
  return Array.from({ length: 7 }, (_, i) => formatter.format(addDays(SUNDAY, (weekStart + i) % 7)));
}

/** Month names, January first. */
export function getMonthNames(locale: string | undefined, style: "long" | "short"): string[] {
  const formatter = getDateFormatter(locale, { month: style });
  return Array.from({ length: 12 }, (_, i) => formatter.format(new Date(2024, i, 1)));
}

/*
 * First day of the week per region, from CLDR. Used only when the browser lacks
 * Intl.Locale#getWeekInfo (Firefox, older Safari). Everything else starts on Monday.
 */
const SUNDAY_FIRST = new Set(
  "AG AS BD BR BS BT BW BZ CA CN CO DM DO ET GT GU HK HN ID IL IN JM JP KE KH KR LA MH MM MO MT MX MZ NI NP PA PE PH PK PR PT PY SA SG SV TH TT TW UM US VE VI WS YE ZA ZW".split(
    " ",
  ),
);
const SATURDAY_FIRST = new Set("AE AF BH DJ DZ EG IQ IR JO KW LY OM QA SD SY".split(" "));

type WeekInfo = { firstDay?: number };
type LocaleWithWeekInfo = Intl.Locale & { getWeekInfo?: () => WeekInfo; weekInfo?: WeekInfo };

/** The locale's first day of the week (0 = Sunday). "en-US" → 0, "en-GB" → 1, "ar-EG" → 6. */
export function getWeekStart(locale?: string): Weekday {
  try {
    const tag = locale ?? (typeof navigator !== "undefined" ? navigator.language : "en-US");
    const loc = new Intl.Locale(tag) as LocaleWithWeekInfo;
    const info = loc.getWeekInfo?.() ?? loc.weekInfo;
    if (info?.firstDay) return (info.firstDay % 7) as Weekday;
    const region = loc.maximize().region ?? "";
    if (SUNDAY_FIRST.has(region)) return 0;
    if (SATURDAY_FIRST.has(region)) return 6;
    if (region === "MV") return 5;
    return 1;
  } catch {
    return 0;
  }
}

/** Whether the locale is written right to left (for arrow-key direction when no `dir` is set). */
export function isRtlLocale(locale?: string): boolean {
  try {
    const loc = new Intl.Locale(
      locale ?? (typeof navigator !== "undefined" ? navigator.language : "en-US"),
    ) as Intl.Locale & {
      getTextInfo?: () => { direction?: string };
      textInfo?: { direction?: string };
    };
    const info = loc.getTextInfo?.() ?? loc.textInfo;
    if (info?.direction) return info.direction === "rtl";
    return ["ar", "he", "fa", "ur", "ps", "dv", "yi", "ckb"].includes(loc.language);
  } catch {
    return false;
  }
}

"use client";

import {
  useEffectEvent,
  useLayoutEffect,
  useRef,
  useState,
  type FocusEvent,
  type KeyboardEvent,
  type ReactNode,
} from "react";
import { AnimatePresence, motion, useIsPresent } from "motion/react";

import { cn } from "../../lib/cn";
import { duration, ease, spring } from "../../motion/tokens";
import { endOfMonth, formatDate, getMonthNames, monthKey, toISODate } from "../date-utils";
import { isRtlAt } from "../../hooks/use-direction";
import { type CalendarLabels, type View } from "./model";

/* ---------- Month grid ---------- */

/** The computed state of one day cell: in month, today, unavailable, selected and range flags. @internal */
export type DayState = {
  inMonth: boolean;
  today: boolean;
  unavailable: boolean;
  selected: boolean;
  rangeStart: boolean;
  rangeEnd: boolean;
  inRange: boolean;
  inPreview: boolean;
  previewStart: boolean;
  previewEnd: boolean;
  /** The day under the pointer / focus that would end the range. */
  previewCap: boolean;
  focusTarget: boolean;
};

/** The props of the month grid. @internal */
export type MonthGridProps = {
  caption: string;
  weeks: Date[][];
  month: Date;
  range: boolean;
  fluid: boolean;
  outsideDays: boolean;
  weekdaysShort: string[];
  weekdaysLong: string[];
  dayState: (date: Date, inMonth: boolean) => DayState;
  formatNumber: (date: Date) => string;
  formatName: (date: Date, state: DayState) => string;
  pillId: string | undefined;
  onSelect: (date: Date) => void;
  onFocusDay: (date: Date) => void;
  onHoverDay: (date: Date) => void;
  onLeave: () => void;
  onKeyDown: (event: KeyboardEvent<HTMLTableElement>) => void;
};

/** The month grid with roving keyboard focus across its days. @internal */
export function MonthGrid({
  caption,
  weeks,
  month,
  range,
  fluid,
  outsideDays,
  weekdaysShort,
  weekdaysLong,
  dayState,
  formatNumber,
  formatName,
  pillId,
  onSelect,
  onFocusDay,
  onHoverDay,
  onLeave,
  onKeyDown,
}: MonthGridProps) {
  const present = useIsPresent();

  function onBlur(event: FocusEvent<HTMLTableElement>) {
    if (!event.currentTarget.contains(event.relatedTarget)) onLeave();
  }

  return (
    <table
      // eslint-disable-next-line jsx-a11y/no-noninteractive-element-to-interactive-role -- the WAI-ARIA date-grid pattern: a <table role="grid"> keeps row/column semantics while arrow keys move between days
      role="grid"
      aria-label={caption}
      aria-multiselectable={range || undefined}
      data-present={present ? "" : undefined}
      aria-hidden={present ? undefined : true}
      onKeyDown={onKeyDown}
      onPointerLeave={onLeave}
      onBlur={onBlur}
      className={cn(
        // Cells share the width: 40px days (44px on touch) that shrink to fit narrow screens.
        "table-fixed border-collapse select-none",
        fluid ? "w-full" : "w-70 max-w-full any-pointer-coarse:w-77",
        !present && "pointer-events-none",
      )}
    >
      <thead>
        <tr>
          {weekdaysShort.map((day, i) => (
            <th
              key={i}
              scope="col"
              abbr={weekdaysLong[i]}
              className="h-8 overflow-hidden p-0 text-center text-2xs font-semibold tracking-wide text-ellipsis whitespace-nowrap text-sheen-fg-muted uppercase"
            >
              {day}
            </th>
          ))}
        </tr>
      </thead>
      <tbody>
        {weeks.map((week, row) => (
          <tr key={row}>
            {week.map((date, col) => {
              const inMonth = date.getMonth() === month.getMonth();
              if (!inMonth) {
                return (
                  <td key={col} className="p-0">
                    {/* Hidden outside days still hold the row's height, so fixedWeeks keeps six rows. */}
                    <span
                      aria-hidden
                      className={cn(
                        "mx-auto flex aspect-square w-full items-center justify-center text-sm text-sheen-fg-subtle tabular-nums",
                        fluid ? "max-w-11" : "max-w-10 any-pointer-coarse:max-w-11",
                        !outsideDays && "invisible",
                      )}
                    >
                      {outsideDays ? formatNumber(date) : ""}
                    </span>
                  </td>
                );
              }
              const s = dayState(date, inMonth);
              const first = date.getDate() === 1;
              const last = date.getDate() === endOfMonth(date).getDate();
              const band =
                s.inRange ||
                s.rangeStart ||
                s.rangeEnd ||
                (s.inPreview && !s.selected) ||
                s.previewStart ||
                s.previewEnd;
              const startsBand = s.rangeStart || (s.previewStart && !s.rangeEnd);
              const endsBand = s.rangeEnd || (s.previewEnd && !s.rangeStart);
              return (
                <td
                  key={col}
                  aria-selected={s.selected || s.inRange || undefined}
                  aria-disabled={s.unavailable || undefined}
                  className={cn(
                    "relative p-0 text-center",
                    // Range band behind the day circles: rounded where it starts and ends,
                    // and at the edges of each week row and of the month.
                    band && [
                      "before:absolute before:inset-y-0 before:content-['']",
                      s.inRange || (s.rangeStart && s.rangeEnd) || s.rangeStart || s.rangeEnd
                        ? "before:bg-sheen-accent-soft"
                        : "before:border-y before:border-dashed before:border-sheen-accent-border before:bg-sheen-hover",
                      startsBand
                        ? "before:start-1/2 before:end-0"
                        : endsBand
                          ? "before:start-0 before:end-1/2"
                          : "before:inset-x-0",
                      (col === 0 || first) && !startsBand && "before:rounded-s-full",
                      (col === 6 || last) && !endsBand && "before:rounded-e-full",
                      startsBand && endsBand && "before:hidden",
                      "forced-colors:before:border-y forced-colors:before:border-solid forced-colors:before:border-[Highlight]",
                    ],
                  )}
                >
                  <DayButton
                    date={date}
                    state={s}
                    number={formatNumber(date)}
                    name={formatName(date, s)}
                    fluid={fluid}
                    pillId={pillId}
                    onSelect={onSelect}
                    onFocusDay={onFocusDay}
                    onHoverDay={onHoverDay}
                  />
                </td>
              );
            })}
          </tr>
        ))}
      </tbody>
    </table>
  );
}

/** One day cell button. @internal */
export function DayButton({
  date,
  state: s,
  number,
  name,
  fluid,
  pillId,
  onSelect,
  onFocusDay,
  onHoverDay,
}: {
  date: Date;
  state: DayState;
  number: string;
  name: string;
  fluid: boolean;
  pillId: string | undefined;
  onSelect: (date: Date) => void;
  onFocusDay: (date: Date) => void;
  onHoverDay: (date: Date) => void;
}) {
  return (
    <button
      type="button"
      data-day={toISODate(date)}
      data-selected={s.selected ? "" : undefined}
      data-today={s.today ? "" : undefined}
      tabIndex={s.focusTarget ? 0 : -1}
      aria-label={name}
      aria-current={s.today ? "date" : undefined}
      aria-disabled={s.unavailable || undefined}
      onClick={() => onSelect(date)}
      onFocus={() => onFocusDay(date)}
      onPointerEnter={(e) => e.pointerType !== "touch" && onHoverDay(date)}
      className={cn(
        "sheen-hit group/day relative z-10 mx-auto flex aspect-square w-full items-center justify-center rounded-full text-sm text-sheen-fg tabular-nums",
        fluid ? "max-w-11" : "max-w-10 any-pointer-coarse:max-w-11",
        "touch-manipulation [-webkit-tap-highlight-color:transparent]",
        "transition-[background-color,color,scale] duration-(--sheen-duration-fast) ease-sheen-out",
        "focus-visible:outline-2 focus-visible:outline-offset-1 focus-visible:outline-sheen-focus",
        !s.selected && !s.unavailable && "hover:bg-sheen-hover motion-ok:active:scale-90",
        s.today && !s.selected && "font-semibold text-sheen-accent",
        s.unavailable && "cursor-not-allowed text-sheen-fg-subtle line-through decoration-sheen-fg-subtle/70",
        s.previewCap && !s.selected && "shadow-[inset_0_0_0_2px_var(--sheen-accent-border)]",
        s.selected && [
          "font-semibold text-sheen-accent-fg",
          // Range ends have no gliding pill: fill the button itself.
          !pillId && "sheen-fill [background-image:var(--sheen-accent-fill)] shadow-(--sheen-accent-fill-shadow)",
          "forced-colors:forced-color-adjust-none forced-colors:bg-[Highlight] forced-colors:text-[HighlightText]",
        ],
      )}
    >
      {s.selected && pillId && (
        // Single mode: one pill that glides from the old day to the new one.
        <motion.span
          aria-hidden
          layoutId={pillId}
          transition={spring.snappy}
          className="sheen-fill absolute inset-0 rounded-full [background-image:var(--sheen-accent-fill)] shadow-(--sheen-accent-fill-shadow) forced-colors:hidden"
        />
      )}
      <span className="relative">{number}</span>
      {s.today && (
        <span
          aria-hidden
          className={cn(
            "absolute bottom-1.5 left-1/2 size-1 -translate-x-1/2 rounded-full",
            s.selected
              ? "bg-sheen-accent-fg forced-colors:bg-[HighlightText]"
              : "bg-sheen-accent forced-colors:bg-[CanvasText]",
          )}
        />
      )}
    </button>
  );
}

/* ---------- Month / year picker ---------- */

/** The props of the month and year picker. @internal */
export type MonthYearPickerProps = {
  view: View;
  year: number;
  visibleMonth: Date;
  today: Date;
  min: Date | null;
  max: Date | null;
  locale: string | undefined;
  labels: CalendarLabels;
  reduced: boolean;
  onYearChange: (year: number) => void;
  onShowYears: () => void;
  onPickYear: (year: number) => void;
  onPickMonth: (month: number) => void;
  onClose: () => void;
};

/** The month and year picker that replaces the day grid. @internal */
export function MonthYearPicker({
  view,
  year,
  visibleMonth,
  today,
  min,
  max,
  locale,
  labels,
  reduced,
  onYearChange,
  onShowYears,
  onPickYear,
  onPickMonth,
  onClose,
}: MonthYearPickerProps) {
  const months = view === "months";
  const yearFormat = { year: "numeric" } as const;
  const fmtYear = (y: number) => formatDate(new Date(y, 0, 1), locale, yearFormat);
  const pageStart = Math.floor(year / 12) * 12;
  const monthNamesShort = getMonthNames(locale, "short");

  const minYear = min?.getFullYear() ?? -Infinity;
  const maxYear = max?.getFullYear() ?? Infinity;
  const prevDisabled = months ? year - 1 < minYear : pageStart - 1 < minYear;
  const nextDisabled = months ? year + 1 > maxYear : pageStart + 12 > maxYear;

  const items = months
    ? monthNamesShort.map((short, i) => {
        const key = year * 100 + i;
        return {
          key,
          text: short,
          label: formatDate(new Date(year, i, 1), locale, { month: "long", year: "numeric" }),
          current: key === monthKey(visibleMonth),
          today: key === monthKey(today),
          disabled: (min !== null && key < monthKey(min)) || (max !== null && key > monthKey(max)),
          value: i,
        };
      })
    : Array.from({ length: 12 }, (_, i) => {
        const y = pageStart + i;
        return {
          key: y,
          text: fmtYear(y),
          label: fmtYear(y),
          current: y === visibleMonth.getFullYear(),
          today: y === today.getFullYear(),
          disabled: y < minYear || y > maxYear,
          value: y,
        };
      });

  // The visible month / year, or (in another year) the same month, so focus stays put visually.
  const found = items.findIndex((it) => it.current);
  const currentIndex = found >= 0 ? found : months ? visibleMonth.getMonth() : -1;
  const [focusIndex, setFocusIndex] = useState(Math.max(0, currentIndex));
  const gridRef = useRef<HTMLDivElement>(null);
  // Focus moves into the grid on open and on every view switch; paging with the header
  // buttons leaves focus on the button, paging with the keyboard keeps it in the grid.
  // Bumped whenever focus must (re)enter the grid; starts at 1 so it enters on open.
  const [focusRequest, setFocusRequest] = useState(1);
  const pageKey = months ? year : pageStart;
  const [seen, setSeen] = useState({ view, pageKey, request: focusRequest });
  if (seen.view !== view) {
    setSeen({ view, pageKey, request: focusRequest + 1 });
    setFocusRequest(focusRequest + 1);
    const next = Math.max(0, currentIndex);
    if (next !== focusIndex) setFocusIndex(next);
  } else if (seen.pageKey !== pageKey) {
    setSeen({ view, pageKey, request: focusRequest });
    // Is focus about to enter the grid (keyboard paging bumped the request)? Then the roving index is already right.
    if (seen.request === focusRequest && currentIndex >= 0 && currentIndex !== focusIndex) setFocusIndex(currentIndex);
  }

  // The roving index is read when focus enters, not watched: moving the index alone must not steal focus.
  const focusCell = useEffectEvent(() => {
    gridRef.current?.querySelector<HTMLElement>(`[data-index="${focusIndex}"]`)?.focus();
  });
  useLayoutEffect(() => {
    focusCell();
  }, [focusRequest]);

  function move(index: number) {
    // Inline, not `lib/math`'s `clamp`: the lower bound wins here, so an empty list resolves to 0 rather than -1.
    const clamped = Math.max(0, Math.min(items.length - 1, index));
    setFocusIndex(clamped);
    setFocusRequest((n) => n + 1);
  }

  function onKeyDown(event: KeyboardEvent<HTMLDivElement>) {
    const rtl = isRtlAt(event.currentTarget);
    const cols = 3;
    const map: Record<string, number> = {
      ArrowLeft: rtl ? 1 : -1,
      ArrowRight: rtl ? -1 : 1,
      ArrowUp: -cols,
      ArrowDown: cols,
    };
    if (event.key === "Escape") {
      event.preventDefault();
      // Keep a surrounding popover open: Escape here only leaves the picker.
      event.stopPropagation();
      onClose();
      return;
    }
    if (event.key in map) {
      event.preventDefault();
      const next = focusIndex + (map[event.key] ?? 0);
      if (next < 0 && !prevDisabled) {
        if (months) onYearChange(year - 1);
        else onYearChange(year - 12);
        move(next + items.length);
        return;
      }
      if (next >= items.length && !nextDisabled) {
        if (months) onYearChange(year + 1);
        else onYearChange(year + 12);
        move(next - items.length);
        return;
      }
      move(next);
    } else if (event.key === "Home") {
      event.preventDefault();
      move(0);
    } else if (event.key === "End") {
      event.preventDefault();
      move(items.length - 1);
    } else if (event.key === "PageUp" || event.key === "PageDown") {
      event.preventDefault();
      const dir = event.key === "PageUp" ? -1 : 1;
      if ((dir < 0 && prevDisabled) || (dir > 0 && nextDisabled)) return;
      onYearChange(months ? year + dir : year + dir * 12);
      setFocusRequest((n) => n + 1);
    }
  }

  const heading = months ? fmtYear(year) : `${fmtYear(pageStart)} – ${fmtYear(pageStart + 11)}`;

  return (
    <motion.div
      initial={reduced ? { opacity: 0 } : { opacity: 0, scale: 1.04 }}
      animate={{
        opacity: 1,
        scale: 1,
        transition: reduced
          ? { duration: duration.fast }
          : { opacity: { duration: duration.base }, scale: spring.snappy },
      }}
      exit={{ opacity: 0, scale: reduced ? 1 : 1.02, transition: { duration: duration.exit, ease: ease.exit } }}
      className="absolute inset-0 flex flex-col gap-2"
    >
      <div className="flex h-10 items-center gap-1 any-pointer-coarse:h-11">
        <NavButton
          label={months ? labels.previousYear : labels.previousYears}
          disabled={prevDisabled}
          onClick={() => onYearChange(months ? year - 1 : year - 12)}
          dir="prev"
        />
        {months ? (
          <CaptionButton
            label={labels.chooseYear(fmtYear(year))}
            expanded
            onClick={onShowYears}
            motionKey={year}
            direction={1}
            reduced={reduced}
          >
            {heading}
          </CaptionButton>
        ) : (
          <span
            className="flex min-w-0 flex-1 items-center justify-center text-sm font-semibold tabular-nums"
            aria-live="polite"
          >
            {heading}
          </span>
        )}
        <NavButton
          label={months ? labels.nextYear : labels.nextYears}
          disabled={nextDisabled}
          onClick={() => onYearChange(months ? year + 1 : year + 12)}
          dir="next"
        />
      </div>
      {/* eslint-disable-next-line jsx-a11y/no-noninteractive-element-interactions -- arrow-key navigation delegated from the focusable cells inside; the group is not a control itself */}
      <div
        ref={gridRef}
        role="group"
        aria-label={heading}
        onKeyDown={onKeyDown}
        className="grid min-h-0 flex-1 grid-cols-3 grid-rows-4 gap-1.5 p-0.5"
      >
        {items.map((item, i) => (
          <button
            key={item.key}
            type="button"
            data-index={i}
            tabIndex={i === focusIndex ? 0 : -1}
            aria-label={item.label}
            aria-pressed={item.current}
            aria-disabled={item.disabled || undefined}
            onFocus={() => setFocusIndex(i)}
            onClick={() => {
              if (item.disabled) return;
              if (months) onPickMonth(item.value);
              else onPickYear(item.value);
            }}
            className={cn(
              "relative flex items-center justify-center rounded-sheen-md text-sm font-medium tabular-nums",
